/**
 * ONOCRA Apple-to-Apple evidence bridge — 2026-10-14.
 * Produces reusable GL *descriptions* from existing source-backed Device.specs.
 * NOT a numeric scoring engine; neither megapixels nor mAh nor row counts prove
 * meaningful improvement. No source evidence is generated by this module.
 *
 * Accepts the currently deployed Device-like objects from src/data/devices.ts.
 * The caller may pass its result to the existing buildLeapReport module.
 */

export type EvidenceKind = 'manufacturer' | 'independent' | 'editorial' | 'unverified';
export type ChangeStatus = 'improved' | 'unchanged' | 'regressed' | 'unverified';
export interface CheckedSpec {
  value?: string;
  numeric?: number;
  source?: string;
  kind?: EvidenceKind;
}
export interface AppleComparable {
  id: string;
  name: string;
  brand: string;
  family?: string;
  year?: number;
  specs?: Record<string, CheckedSpec>;
}
export interface AppleGLRow {
  feature: string;
  status: ChangeStatus;
  headline: string;
  detail: string;
  evidence: string;
  kind: EvidenceKind;
  confidence: 'low' | 'medium' | 'high';
  asOf: string;
}
export interface AppleGLSet {
  family: string;
  familyLabel: string;
  from: string;
  to: string;
  verdict: string;
  rows: AppleGLRow[];
}

function isChecked(s?: CheckedSpec): s is CheckedSpec & { value:string; source:string } {
  if (!s || s.kind === 'unverified' || !s.value || !s.source) return false;
  try { return new URL(s.source).protocol === 'https:'; } catch { return false; }
}
function value(s?: CheckedSpec): string | null { return isChecked(s) ? s.value!.trim() : null; }
function numberFrom(s:CheckedSpec | undefined, type:'storage'|'ram'|'display'|'refresh'|'battery'):number|null {
  if (!isChecked(s))return null;
  const str=s.value!;
  let hits: number[]=[];
  if(type==='storage'){
    hits=Array.from(str.matchAll(/(\d+(?:\.\d+)?)\s*(TB|GB)\b/gi),m=>Number(m[1])*(m[2].toUpperCase()==='TB'?1024:1));
    return hits.length ? Math.min(...hits) : null;
  }
  const rx={ram:/(\d+(?:\.\d+)?)\s*GB\b/i,display:/(\d+(?:\.\d+)?)\s*(?:-?inch|[“”"])/i,refresh:/(\d+(?:\.\d+)?)\s*Hz\b/i,battery:/(\d[\d,]*)\s*mAh\b/i}[type];
  const m=str.match(rx);return m ? Number(m[1].replace(/,/g,'')) : null;
}
function comparableKind(a:CheckedSpec,b:CheckedSpec):EvidenceKind {
  return a.kind==='independent'||b.kind==='independent' ? 'independent'
    : a.kind==='manufacturer'&&b.kind==='manufacturer' ? 'manufacturer':'editorial';
}
function line(feature:string,older:AppleComparable,newer:AppleComparable,key:string,mode:'quantity'|'preference'|'text',units:string,parseType?:'storage'|'ram'|'display'|'refresh'|'battery'):AppleGLRow {
  const a=older.specs?.[key],b=newer.specs?.[key];
  const base:AppleGLRow={feature,status:'unverified',headline:'Not enough comparable published evidence',detail:`We do not have comparable, source-linked ${feature.toLowerCase()} details for both phones.`,evidence:'Not verified for both phones',kind:'unverified',confidence:'low',asOf:'2026-10-14 (assessment date)'};
  if(!isChecked(a)||!isChecked(b))return base;
  const av=value(a)!,bv=value(b)!;
  const x=parseType?numberFrom(a,parseType):null, y=parseType?numberFrom(b,parseType):null;
  const kind=comparableKind(a,b);
  const common={evidence:`Previous: ${a.source} | Selected: ${b.source}`,kind,confidence:'medium' as const};
  if(mode==='text'){
    const same=av.toLowerCase()===bv.toLowerCase();
    return {...base,...common,headline:same?'Published descriptions are the same':'Published descriptions differ',detail:same?`Both phones list ${av}. This does not establish identical real-world quality.`:`Previous: ${av}. Selected: ${bv}. A difference in camera or charging descriptions alone does not prove a better experience.`,status:same?'unchanged':'unverified'};
  }
  if(x===null||y===null)return {...base,...common,headline:`${av} → ${bv}`,detail:'The wording is not sufficiently consistent to rate this change fairly.'};
  const shown=(n:number)=>`${n.toLocaleString('en-US')}${units}`;
  const same=Math.abs(x-y)<0.001;
  const status:ChangeStatus=same?'unchanged':mode==='quantity'?(y>x?'improved':'regressed'):'unverified';
  const note=mode==='quantity'
    ? `The published specification ${y>x?'increases':y<x?'decreases':'stays the same'}. This alone does not establish a noticeable real-world difference.`
    : `This is a preference or capacity difference, not a measured improvement. A larger screen or battery does not necessarily make a phone better for you.`;
  return {...base,...common,status,headline:`${shown(x)} → ${shown(y)}`,detail:note};
}
function appleTier(name:string):string{
  const n=name.toLowerCase();
  if(/\bpro max\b/.test(n))return 'Pro Max';
  if(/\bpro\b/.test(n))return 'Pro';
  if(/\bplus\b/.test(n))return 'Plus';
  if(/\b\d+e\b/.test(n))return 'e';
  if(/\bair\b/.test(n))return 'Air';
  if(/\bduo\b/.test(n))return 'Duo';
  return 'Standard';
}
export function buildAppleGLFromEvidence(older:AppleComparable|null|undefined,newer:AppleComparable|null|undefined):AppleGLSet|null {
  if(!older||!newer||older.id===newer.id||older.brand.toLowerCase()!=='apple'||newer.brand.toLowerCase()!=='apple')return null;
  const rows:AppleGLRow[]=[
    line('Starting storage',older,newer,'storage','quantity',' GB','storage'),
    line('Memory (RAM)',older,newer,'ram','quantity',' GB','ram'),
    line('Screen refresh rate',older,newer,'refresh','quantity',' Hz','refresh'),
    line('Screen size',older,newer,'display','preference',' inches','display'),
    line('Battery capacity',older,newer,'battery','preference',' mAh','battery'),
    line('Camera specifications',older,newer,'cameras','text',''),
    line('Charging specifications',older,newer,'charging','text',''),
  ];
  const checked=rows.filter(r=>r.kind!=='unverified').length;
  // A link alone does not make an unsupported comparison useful: if neither
  // model supplies a source-backed comparable row, fall through to the page's
  // ordinary "research unavailable" presentation.
  if (checked === 0) return null;
  const more=rows.filter(r=>r.status==='improved').map(r=>r.feature.toLowerCase());
  const sameTier=appleTier(older.name)===appleTier(newer.name);
  const successive=!!older.year && !!newer.year && newer.year-older.year===1;
  const relationship=successive&&sameTier?'a direct previous-generation comparison'
    :successive?'a comparison across different versions of consecutive iPhone generations'
    :'a comparison between two selected Apple phones';
  const changes=more.length?`The source-backed specifications show increases in ${more.slice(0,3).join(', ')}.`
    :'We have not established a clear improvement in the limited comparable measurements.';
  const verdict=`This is ${relationship}. ${changes} ${checked} of 7 categories have source-linked information for both phones. We have not checked enough independent camera, speed, battery-life and cost evidence to recommend an upgrade from these specifications alone.`;
  return {family:newer.family||'apple-iphone',familyLabel:'Apple iPhone — source-backed specification comparison',from:older.id,to:newer.id,verdict,rows};
}

export function appleEvidenceSynopsis(older:AppleComparable|null|undefined,newer:AppleComparable|null|undefined):string|null {
  const result=buildAppleGLFromEvidence(older,newer);
  if(!result)return null;
  const improved=result.rows.filter(x=>x.status==='improved');
  const missing=result.rows.filter(x=>x.kind==='unverified');
  return `${improved.length?`Published specifications show gains in ${improved.map(x=>x.feature.toLowerCase()).join(', ')}. `:''}${missing.length?`${missing.length} of 7 areas still lack a like-for-like, source-backed comparison. `:''}For ${older!.name} versus ${newer!.name}, bigger numbers alone do not prove that changing phones is worth the money.`;
}
